function radixSort(numbers, maxDigits):
    if length(numbers) == 0 or maxDigits <= 0:
        return numbers

    buckets = new array[10] of empty arrays
    bucketSizes = new array[10] of 0

    for each number in numbers:
        digit = (number // (maxDigits // 10)) % 10
        buckets[digit].append(number)
        bucketSizes[digit]++

    for i from 0 to 9:
        buckets[i] = radixSort(buckets[i], maxDigits // 10)

    result = new array of length sum(bucketSizes)
    index = 0
    for i from 0 to 9:
        for j from 0 to bucketSizes[i] - 1:
            result[index] = buckets[i][j]
            index++

    return result

